function setWeapon(type,quiet=false){const valid=['rifle','machine','shotgun','plasma','laser'];if(!valid.includes(type))return;state.weapon=type;state.weaponLevel=valid.indexOf(type)+1;if(weaponRoot)playerParts.gun.remove(weaponRoot);let visual=weaponModels[type];if(!visual){const root=buildGun(type),flash=mesh(new THREE.ConeGeometry(.09,.32,8),mat('muzzle'+type,type==='plasma'?'#c29aff':type==='laser'?'#ff8bfb':'#fff0b1',.18,.05,2),root,[0,0,-.91],[.42,1,.65]);flash.rotation.x=-Math.PI/2;flash.visible=false;visual=weaponModels[type]={root,muzzle:flash}}weaponRoot=visual.root;muzzle=visual.muzzle;playerParts.gun.add(weaponRoot);updateWeaponUi();if(!quiet){announce(`${weaponInfo[type].name} 已装备`,`火力模式切换`);audio.pickup();burst3D(playerRig.position.x,1.4,playerZ-.4,weaponInfo[type].color,20)}}
