function labelSprite(lines,color='#b7ffff'){const c=document.createElement('canvas');c.width=512;c.height=350;const x=c.getContext('2d');x.clearRect(0,0,512,350);const grad=x.createLinearGradient(0,0,0,350);grad.addColorStop(0,'rgba(6,21,31,.88)');grad.addColorStop(1,'rgba(6,21,31,.58)');x.fillStyle=grad;x.beginPath();x.roundRect(8,8,496,334,28);x.fill();x.strokeStyle=color;x.lineWidth=7;x.shadowColor=color;x.shadowBlur=20;x.stroke();x.shadowBlur=0;x.textAlign='center';x.textBaseline='middle';x.fillStyle='#f3ffff';x.font='900 119px system-ui,"Noto Sans SC",sans-serif';x.fillText(lines.value,256,137);x.fillStyle=color;x.font='800 42px system-ui,"Noto Sans SC",sans-serif';x.fillText(lines.name,256,232);x.fillStyle='#d1e7e6';x.font='600 22px system-ui,sans-serif';x.fillText(lines.hint||'选择此路线',256,293);const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,depthWrite:false}));sprite.scale.set(3.35,2.3,1);sprite.position.set(0,3.35,-.16);return{sprite,canvas:c,texture:tex,ctx:x}}
