function buildGate(reward,x,z){const group=new THREE.Group();group.position.set(x,0,z);scene.add(group);const color=reward.color;const glow=mat('gateGlow'+color,color,.23,.1,1.5);const frame=mat('gateFrame'+color,'#263942',.35,.7);const w=2.25,h=4.65;for(const s of [-1,1]){addBox(group,[s*w/2,h/2,0],[.14,h,.17],undefined,frame);addBox(group,[s*w/2,h/2,-.04],[.07,h-.1,.07],undefined,glow)}addBox(group,[0,h,0],[w,.16,.2],undefined,frame);addBox(group,[0,h,.015],[w-.12,.06,.08],undefined,glow);const holo=mesh(new THREE.PlaneGeometry(w-.22,h-.32),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.105,side:THREE.DoubleSide,depthWrite:false}),group,[0,h/2,.1]);const scan=mesh(new THREE.PlaneGeometry(w-.3,.035),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.62,depthWrite:false}),group,[0,1.2,.11]);const lbl=labelSprite({value:reward.value,name:reward.name,hint:'射击增幅 · 迎面穿越',},color);group.add(lbl.sprite);group.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});const light=new THREE.PointLight(color,5,6,2);light.position.set(0,2.2,.35);group.add(light);state.gates.push({group,reward:{...reward},charge:0,x,z,light,label:lbl,scan,phase:rand(0,6),resolved:false})}
function makeCrateTexture(type){const c=document.createElement('canvas');c.width=512;c.height=260;const x=c.getContext('2d'),color=weaponInfo[type].color;x.fillStyle='rgba(8,18,29,.94)';x.beginPath();x.roundRect(5,5,502,250,25);x.fill();x.strokeStyle=color;x.lineWidth=5;x.stroke();x.textAlign='center';x.fillStyle=color;x.font='900 45px system-ui,"Noto Sans SC"';x.fillText('武器补给',256,85);x.fillStyle='#ffffff';x.font='900 68px system-ui,"Noto Sans SC"';x.fillText(weaponInfo[type].name,256,165);x.fillStyle='#cbdfdf';x.font='600 26px system-ui,"Noto Sans SC"';x.fillText(['标准级','军用级','突击级','实验级','原型级'][['rifle','machine','shotgun','plasma','laser'].indexOf(type)]+'  ·  靠近拾取',256,215);const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;return new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,depthWrite:false}))}
function spawnCrate(type,x=rand(-3.7,3.7),z=-29){const group=new THREE.Group();group.position.set(x,.4,z);scene.add(group);const color=weaponInfo[type].color;const crate=addBox(group,[0,0,0],[1.1,.8,.8],undefined,mat('crate'+type,'#263941',.38,.75));crate.rotation.y=.12;addBox(group,[0,.04,-.43],[.84,.49,.055],undefined,mat('crateGlow'+type,color,.22,.25,1.4));for(const s of [-1,1])addBox(group,[s*.48,.39,0],[.1,.09,.85],undefined,mat('crateEdge'+type,color,.3,.6,.75));const top=addBox(group,[0,.43,0],[1.08,.08,.82],undefined,mat('crateTop'+type,'#40545a',.36,.68));const sprite=makeCrateTexture(type);sprite.position.set(0,1.65,0);sprite.scale.set(2.9,1.47,1);group.add(sprite);const light=new THREE.PointLight(color,4,7,2);light.position.y=1;group.add(light);state.crates.push({group,type,x,z,spin:rand(0,6),light})}
function chooseGatePair(){const phase=Math.min(gateDefs.length-1,Math.floor(Math.max(0,state.time)/18));let pair=gateDefs[phase].map(x=>({...x}));if(state.time>25&&Math.random()<.28){const types=['machine','shotgun','plasma','laser'];const available=types.filter(t=>t!==state.weapon);const t=available[Math.floor(Math.random()*available.length)];return[pair[0],pair[1],{type:'gun',weapon:t,value:'武器补给',name:weaponInfo[t].name,color:weaponInfo[t].color}]}return pair}
