function acquireGate(g){if(g.reward.type==='gun'){setWeapon(g.reward.weapon);state.score+=150;return}const s=state.stats;switch(g.reward.type){case'lanes':s.lanes=Math.min(9,s.lanes+g.reward.amount);break;case'pellets':s.pellets=Math.min(12,s.pellets+g.reward.amount);break;case'rate':s.fireRate=Math.min(2.5,s.fireRate*(1+g.reward.amount));break;case'speed':s.bulletSpeed=Math.min(2.2,s.bulletSpeed*(1+g.reward.amount));break;case'damage':s.damage=Math.min(3,s.damage*(1+g.reward.amount));break}state.weaponLevel=Math.min(9,state.weaponLevel+1);state.score+=45;state.combo++;const extra=g.charge>=8?Math.min(1.25,g.charge*.035):0;if(extra){if(g.reward.type==='lanes')s.lanes=Math.min(9,s.lanes+1);else if(g.reward.type==='pellets')s.pellets=Math.min(12,s.pellets+1);else if(g.reward.type==='rate')s.fireRate=Math.min(2.5,s.fireRate*1.1);else if(g.reward.type==='speed')s.bulletSpeed=Math.min(2.2,s.bulletSpeed*1.1);else if(g.reward.type==='damage')s.damage=Math.min(3,s.damage*1.12)}announce(g.reward.value,extra?'射击充能成功 · 额外强化':'战斗属性即时生效');audio.pickup();state.shake=Math.max(state.shake,extra?.18:.1);navigator.vibrate?.(extra?32:18);burst3D(g.x,2,playerZ-.1,g.reward.color,32);updateWeaponUi()}
