function spawnEnemy(type='grunt',x=rand(-4.4,4.4),z=-46){const cfg={grunt:{hp:26,speed:5.2,damage:9,scale:1,score:12},runner:{hp:22,speed:8.2,damage:11,scale:.85,score:18},heavy:{hp:96,speed:3.7,damage:16,scale:1.27,score:28},ranged:{hp:38,speed:3.5,damage:10,scale:.92,score:22},elite:{hp:195,speed:4.4,damage:20,scale:1.48,score:65}}[type]||{hp:26,speed:5,damage:9,scale:1,score:12};const group=createSoldier(type==='grunt'?'scout':type);group.scale.setScalar(cfg.scale);group.position.set(x,0,z);scene.add(group);const barGroup=new THREE.Group();const back=mesh(G.plane,basic('#1d1718',.92),barGroup,[0,2.45,0],[.9,.095,1]);const fill=mesh(G.plane,basic(type==='elite'?'#ff6a54':'#ffc270',.96),barGroup,[0,2.45,.006],[.88,.06,1]);barGroup.position.y=0;group.add(barGroup);const shadow=mesh(new THREE.CircleGeometry(.55*cfg.scale,18),new THREE.MeshBasicMaterial({color:'#050b0d',transparent:true,opacity:.38,depthWrite:false}),scene,[x,-.085,z],[1,.22,1]);shadow.rotation.x=-Math.PI/2;state.threats.push({type,group,shadow,x,z,hp:cfg.hp*(1+Math.min(.85,state.time/220)),maxHp:cfg.hp*(1+Math.min(.85,state.time/220)),speed:cfg.speed*(1+Math.min(.55,state.time/170)),damage:cfg.damage,score:cfg.score,phase:rand(0,8),charge:0,fire:rand(2,5),cooldown:0,stun:0,dead:0,bar:fill,barGroup,attackWarn:0})}
function createDamageSprite(value,color){if(state.floating.length>=24)return;const c=document.createElement('canvas');c.width=192;c.height=72;const x=c.getContext('2d');x.font='900 48px system-ui';x.textAlign='center';x.lineWidth=6;x.strokeStyle='#0a1115';x.strokeText(String(value),96,53);x.fillStyle=color;x.shadowColor=color;x.shadowBlur=14;x.fillText(String(value),96,53);const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,depthWrite:false}));sp.scale.set(1.15,.44,1);scene.add(sp);state.floating.push({mesh:sp,texture:tex,life:.74,max:.74})}
const particlePool=[];function burst3D(x,y,z,color,count=12){const n=Math.min(count,30);for(let i=0;i<n;i++){let p=particlePool.pop();if(!p){p=new THREE.Mesh(G.smallSphere,new THREE.MeshBasicMaterial({color,transparent:true,opacity:1,depthWrite:false}));scene.add(p);p.userData.v=new THREE.Vector3()}p.visible=true;p.material.color.set(color);p.material.opacity=1;p.position.set(x+rand(-.18,.18),y+rand(-.2,.2),z);p.scale.setScalar(rand(.035,.095));p.userData.v.set(rand(-5,5),rand(-1,5),rand(-6,4));p.userData.life=p.userData.max=rand(.22,.54);state.effects.push(p)}}
function muzzleFlash(){if(!muzzle)return;const current=muzzle;current.visible=true;current.scale.y=rand(.65,1.5);setTimeout(()=>{current.visible=false},55)}
function acquireBullet(){let b=state.bullets.find(x=>!x.active);if(!b){if(state.bullets.length>=260)return null;const group=new THREE.Group(),core=mesh(G.smallSphere,mat('bulletCore','#d7ffff',.2,.05,2),group,[0,0,0],[.08,.08,.2]),tail=mesh(G.smallSphere,basic('#60eff0',.72),group,[0,0,.18],[.05,.05,.2]);scene.add(group);b={group,core,tail,active:false,x:0,z:0,vx:0,vz:0,damage:1,life:0,kind:'bullet',color:'#7afff2',radius:.18};state.bullets.push(b)}b.active=true;b.group.visible=true;return b}
function releaseBullet(b){b.active=false;b.group.visible=false}
function createShot(type,targetX){const info=weaponInfo[type],stats=state.stats,lanes=stats.lanes,pellets=type==='shotgun'?Math.max(info.count,stats.pellets+5):stats.pellets;const total=Math.min(72,lanes*pellets),baseDamage=info.damage*stats.damage*(type==='shotgun'?1:1);const muzzleX=state.playerX+.52;let idx=0;for(let lane=0;lane<lanes;lane++){const laneOffset=(lane-(lanes-1)/2)*.42;for(let p=0;p<pellets;p++){if(idx>=total)break;const spread=type==='shotgun'?((p-(pellets-1)/2)*info.spread):((p-(pellets-1)/2)*.035);const aimX=targetX+laneOffset+spread*8;const dx=aimX-muzzleX, dz=-35;const len=Math.hypot(dx,dz);const b=acquireBullet();if(!b)break;b.kind=info.kind;b.x=muzzleX;b.z=playerZ-.35;b.group.position.set(b.x,1.27,b.z);b.vx=dx/len*info.speed*stats.bulletSpeed;b.vz=dz/len*info.speed*stats.bulletSpeed;b.damage=baseDamage/(type==='shotgun'?1:Math.max(1,Math.ceil(pellets*.7)));b.life=3.2;b.color=info.color;b.radius=type==='plasma'?.44:type==='pellet'?.1:.12;const col=new THREE.Color(info.color);b.core.material.color.copy(col);b.core.material.emissive.copy(col);b.tail.material.color.copy(col);b.core.scale.setScalar(type==='plasma'?.36:type==='pellet'?.07:.09);b.tail.scale.set(.045,.045,type==='plasma'?.72:.26);idx++}}}
function doLaser(){const s=state.stats,tx=closestTargetX();const dx=tx-state.playerX-.52,len=Math.hypot(dx,28),vx=dx/len,vz=-28/len,origin=new THREE.Vector3(state.playerX+.52,1.26,playerZ-.35),end=origin.clone().add(new THREE.Vector3(vx,0,vz).multiplyScalar(28));if(!state.laserBeam){const geo=new THREE.CylinderGeometry(.08,.08,1,8),outer=new THREE.Mesh(geo,new THREE.MeshBasicMaterial({color:'#ff4fec',transparent:true,opacity:.7,depthWrite:false})),inner=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,1,7),new THREE.MeshBasicMaterial({color:'#fff0ff',transparent:true,opacity:.95,depthWrite:false}));const g=new THREE.Group();g.add(outer,inner);scene.add(g);state.laserBeam={group:g,outer,inner,life:0}}const beam=state.laserBeam;beam.life=.12;beam.group.visible=true;const mid=origin.clone().add(end).multiplyScalar(.5),axis=end.clone().sub(origin);beam.group.position.copy(mid);beam.group.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),axis.clone().normalize());beam.outer.scale.set(1,axis.length(),1);beam.inner.scale.set(1,axis.length(),1);beam.group.children[0].material.opacity=.7+Math.random()*.25;for(const e of state.threats){if(e.dead)continue;const q=e.group.position.clone().sub(origin);const proj=q.dot(axis.clone().normalize());if(proj>0&&proj<axis.length()&&Math.abs(q.x-vx*proj)<.7){damageEnemy(e,weaponInfo.laser.damage*s.damage,false)}}for(const gate of state.gates){if(!gate.resolved&&Math.abs(gate.x-state.playerX)<1.4){gate.charge=Math.min(16,gate.charge+1);updateGateLabel(gate)}}audio.shoot('laser')}
function updateGateLabel(g){g.label.ctx.clearRect(0,0,512,350);const x=g.label.ctx,co=g.reward.color;x.fillStyle='rgba(6,21,31,.88)';x.beginPath();x.roundRect(8,8,496,334,28);x.fill();x.strokeStyle=co;x.lineWidth=7;x.shadowColor=co;x.shadowBlur=18;x.stroke();x.shadowBlur=0;x.textAlign='center';x.textBaseline='middle';x.fillStyle='#f3ffff';x.font='900 119px system-ui,"Noto Sans SC"';x.fillText(g.reward.value,256,137);x.fillStyle=co;x.font='800 42px system-ui,"Noto Sans SC"';x.fillText(g.reward.name,256,232);x.fillStyle='#d1e7e6';x.font='600 22px system-ui';x.fillText(g.charge>=8?'充能完成 · 额外增幅':'射击充能 '+g.charge+'/8',256,293);g.label.texture.needsUpdate=true}
function fireWeapon(){const type=state.weapon;state.shootTimer=weaponInfo[type].interval/state.stats.fireRate;if(type==='laser'){doLaser();muzzleFlash();return}const target=closestTargetX();createShot(type,target);muzzleFlash();audio.shoot(type);if(type==='shotgun'){state.shake=.16;navigator.vibrate?.(10)}else if(type==='plasma'){state.shake=.11}}
function closestTargetX(){let t=state.playerX;let best=Infinity;for(const e of state.threats){if(e.dead)continue;const dz=Math.abs(e.z-playerZ);if(dz<best){best=dz;t=e.x}}if(state.boss&&!state.boss.dead&&Math.abs(state.boss.z-playerZ)<best)t=state.boss.x;return t}
function processBulletCollisions(b,dt){for(const gate of state.gates){if(gate.resolved)continue;if(Math.abs(b.z-gate.z)<1.15&&Math.abs(b.x-gate.x)<2.25){gate.charge=Math.min(16,gate.charge+(b.kind==='plasma'?3:1));updateGateLabel(gate);releaseBullet(b);return true}}for(let i=state.threats.length-1;i>=0;i--){const e=state.threats[i];if(e.dead)continue;if(Math.abs(b.z-e.z)<.62*e.group.scale.x+ b.radius&&Math.abs(b.x-e.x)<.58*e.group.scale.x+b.radius){if(b.kind==='plasma'){for(const other of state.threats){if(!other.dead&&Math.hypot(other.x-e.x,other.z-e.z)<2.7)damageEnemy(other,b.damage,true)}burst3D(e.x,1.05,e.z,weaponInfo.plasma.color,26);audio.explosion();state.shake=.24}else{damageEnemy(e,b.damage,false)}releaseBullet(b);return true}}if(state.boss&&!state.boss.dead&&Math.abs(b.z-state.boss.z)<1.5&&Math.abs(b.x-state.boss.x)<2.2){damageBoss(b.damage);if(b.kind==='plasma'){burst3D(state.boss.x,2,state.boss.z,weaponInfo.plasma.color,22);audio.explosion();state.shake=.24}releaseBullet(b);return true}return false}
function damageEnemy(e,dmg,heavy){if(e.dead)return;e.hp-=dmg;e.stun=.11;e.group.userData.body.material.emissive.set('#ffffff');e.group.userData.body.material.emissiveIntensity=.55;setTimeout(()=>{if(e.group?.userData.body){e.group.userData.body.material.emissiveIntensity=.04}},65);createDamageSprite(Math.max(1,Math.round(dmg)),heavy?'#ffc17b':'#e9ffff');burst3D(e.x,1.05,e.z,heavy?'#ffd17e':'#a3f8ed',heavy?10:4);audio.impact(heavy);state.lastHit=state.time;state.combo=Math.min(99,state.combo+1);if(e.hp<=0){e.dead=.48;e.group.userData.dead=true;state.kills++;state.score+=e.score;state.combo++;audio.impact(e.type==='elite'||e.type==='heavy');burst3D(e.x,1,e.z,e.type==='elite'?'#ff7059':'#f4a46c',e.type==='elite'?22:12);if(Math.random()<.045&&e.type!=='grunt')spawnCrate(['machine','shotgun','plasma','laser'][Math.floor(Math.random()*4)],e.x,e.z-2)}}
function damageBoss(dmg){const b=state.boss;if(!b||b.dead)return;b.hp-=dmg;b.flash=.1;createDamageSprite(Math.round(dmg),'#ffd7a1');burst3D(b.x,2.3,b.z,'#ff9a73',5);audio.impact(true);state.shake=Math.max(state.shake,.08);if(b.hp<=0){b.dead=true;b.death=1.35;state.score+=1400+Math.floor(state.time*2);state.kills+=1;state.hp=Math.min(100,state.hp+25);audio.explosion();announce('巨像核心击破','高额战斗积分 · 装甲修复');navigator.vibrate?.([35,25,55]);burst3D(b.x,2,b.z,'#ffbd70',45);audio.setBoss(false)}}
function spawnEnemyShot(enemy){const warning=mesh(new THREE.RingGeometry(.16,.27,24),new THREE.MeshBasicMaterial({color:'#ff4f59',transparent:true,opacity:.8,side:THREE.DoubleSide,depthWrite:false}),scene,[state.playerX,.018,playerZ-2]);warning.rotation.x=-Math.PI/2;state.effects.push(warning);warning.userData.life=enemy.type==='ranged'?.7:.5;warning.userData.warning=true;const start={x:enemy.x,z:enemy.z,y:1.1};state.enemyShots.push({x:start.x,z:start.z,y:start.y,vx:(state.playerX-start.x)*.28,vz:8.5,life:3,damage:enemy.damage,warningAt:state.time+.55,active:false,mesh:null})}
function buildBoss(){const type='boss',group=createSoldier(type);group.position.set(0,0,-30);scene.add(group);const hp=650+Math.min(350,state.time*2);state.boss={group,x:0,z:-30,hp,maxHp:hp,move:0,attack:2.2,warning:0,phase:'idle',flash:0,dead:false};state.bossHud=true;$('#bossHud').classList.remove('hidden');$('#bossLabel').textContent='灾厄巨像';audio.setBoss(true);audio.bossAlert();state.shake=.32;navigator.vibrate?.([40,30,70]);burst3D(0,1.8,-30,'#ff604f',35)}
function spawnRoundEnemy(){const t=state.time;let type='grunt';const r=Math.random();if(t<15)type=r<.13?'runner':'grunt';else if(t<40)type=r<.22?'runner':r<.32?'ranged':'grunt';else if(t<70)type=r<.22?'runner':r<.46?'heavy':r<.62?'ranged':'grunt';else type=r<.22?'elite':r<.42?'heavy':r<.62?'runner':r<.78?'ranged':'grunt';spawnEnemy(type,rand(-5.1,5.1),-44-rand(0,12))}
function spawnInterval(t){return t<15?1.32:t<40?.86:t<70?.56:t<78?.48:t<90?.43:mix(.43,.28,Math.min(1,(t-90)/160))}
function updateDifficulty(dt){const t=state.time,interval=spawnInterval(t);state.spawnTimer-=dt;if(state.spawnTimer<=0){state.spawnTimer=interval*rand(.77,1.2);spawnRoundEnemy();if(t>40&&t<70&&Math.random()<.26)spawnEnemy('grunt',rand(-5,5),-47)}state.gateTimer-=dt;if(state.gateTimer<=0&&state.gates.length<6)spawnGateEvent();state.crateTimer-=dt;if(state.crateTimer<=0&&state.crates.length<2){const type=state.time<18?'machine':['machine','shotgun','plasma','laser'][Math.floor(Math.random()*4)];spawnCrate(type,rand(-3.8,3.8));state.crateTimer=rand(19,24)}if(t>=state.nextBoss&&!state.boss){buildBoss();state.nextBoss+=88}}
function moveThreats(dt){for(let i=state.threats.length-1;i>=0;i--){const e=state.threats[i];if(e.dead){e.dead-=dt;e.group.rotation.z+=dt*1.5;e.group.position.y=Math.max(-.35,e.group.position.y-dt*.7);e.group.scale.multiplyScalar(Math.max(.94,1-dt*.58));if(e.dead<=0){disposeSoldier(e.group);scene.remove(e.shadow);state.threats.splice(i,1)}continue}e.stun=Math.max(0,e.stun-dt);e.phase+=dt;const dz=playerZ-e.z,dist=Math.abs(dz);if(e.type==='runner'){if(e.charge>0){e.charge-=dt;e.x=mix(e.x,e.targetX,Math.min(1,dt*4));e.z+=e.speed*2.15*dt}else if(e.charge===0&&dist<29){e.charge=-1.1;e.targetX=clamp(state.playerX+rand(-1.1,1.1),-PLAYER_LIMIT,PLAYER_LIMIT)}else if(e.charge<0){e.charge+=dt;if(e.charge>=0){e.charge=.62;const ring=mesh(new THREE.RingGeometry(.2,.34,24),new THREE.MeshBasicMaterial({color:'#ff634f',transparent:true,opacity:.8,side:THREE.DoubleSide}),scene,[state.playerX,.02,playerZ]);ring.rotation.x=-Math.PI/2;ring.userData.life=.52;ring.userData.warning=true;state.effects.push(ring)}}else{e.x=mix(e.x,state.playerX,dt*.55);e.z+=e.speed*dt}}else if(e.type==='ranged'){e.x=mix(e.x,state.playerX+Math.sin(e.phase)*1.4,dt*.28);if(dist>16)e.z+=e.speed*dt;e.fire-=dt;if(e.fire<=0&&dist<34){e.fire=rand(3.2,4.1);spawnEnemyShot(e)}}else{e.x=mix(e.x,state.playerX+Math.sin(e.phase*1.5)*.4,dt*(e.type==='heavy'?.22:.62));e.z+=e.speed*dt}
if(e.stun>0)e.z-=e.stun*.8*dt;e.group.position.set(e.x,Math.max(0,Math.sin(e.phase*8)*.035),e.z);e.group.userData.legL.rotation.x=Math.sin(e.phase*8)*.45;e.group.userData.legR.rotation.x=-Math.sin(e.phase*8)*.45;e.group.userData.armL.rotation.x=-.22+Math.sin(e.phase*8)*.28;e.group.userData.armR.rotation.x=-.38-Math.sin(e.phase*8)*.25;e.group.userData.body.rotation.z=Math.sin(e.phase*4)*.025;e.shadow.position.set(e.x,-.08,e.z);e.bar.scale.x=Math.max(.02,e.hp/e.maxHp);e.bar.position.x=-(1-e.hp/e.maxHp)*.44;e.barGroup.quaternion.copy(camera.quaternion);if(dist<1.25&&Math.abs(e.x-state.playerX)<.9){hurtPlayer(e.damage, .8);e.z-=2.1;e.x+=Math.sign(e.x-state.playerX||1)*.45}if(e.z>playerZ+8){disposeSoldier(e.group);scene.remove(e.shadow);state.threats.splice(i,1)}}}
function updateBoss(dt){const b=state.boss;if(!b)return;if(b.dead){b.death-=dt;b.group.rotation.y+=dt*2;b.group.scale.multiplyScalar(Math.max(.95,1-dt*.2));if(b.death<=0){disposeSoldier(b.group);state.boss=null;$('#bossHud').classList.add('hidden');audio.setBoss(false)}return}b.move+=dt;b.x=Math.sin(b.move*.45)*3.25;b.z=mix(b.z,-18,Math.min(1,dt*.5));b.group.position.set(b.x,Math.sin(b.move*1.6)*.08,b.z);b.group.rotation.y=Math.PI+Math.sin(b.move*.4)*.12;b.group.userData.legL.rotation.x=Math.sin(b.move*3)*.08;b.attack-=dt;if(b.attack<=0&&b.phase==='idle'){b.phase='warn';b.warning=.85;b.attack=3.2;const target=clamp(state.playerX+rand(-.8,.8),-4.7,4.7);b.targetX=target;const warn=mesh(new THREE.PlaneGeometry(2.8,17),new THREE.MeshBasicMaterial({color:'#ff2846',transparent:true,opacity:.2,side:THREE.DoubleSide,depthWrite:false}),scene,[target,.015,(playerZ+b.z)/2]);warn.rotation.x=-Math.PI/2;warn.userData.warning=true;warn.userData.life=.85;state.effects.push(warn);b.warnMesh=warn;audio.bossAlert();navigator.vibrate?.(22)}if(b.phase==='warn'){b.warning-=dt;if(b.warnMesh)b.warnMesh.material.opacity=.15+Math.sin(state.time*35)*.12;if(b.warning<=0){b.phase='idle';b.warnMesh?.parent?.remove(b.warnMesh);b.warnMesh=null;for(let i=-1;i<=1;i++)spawnBossShot(b,i);state.shake=.12}}if(b.z>playerZ-3.8&&Math.abs(b.x-state.playerX)<1.4)hurtPlayer(24,1.1);$('#bossBar').style.width=`${Math.max(0,b.hp/b.maxHp*100)}%`}
function spawnBossShot(b,i){const meshObj=mesh(G.sphere,mat('bossShot','#ff5667',.25,.1,1.8),scene,[b.x+i*.65,1.3,b.z+1],[.23,.23,.23]);state.enemyShots.push({mesh:meshObj,x:b.x+i*.65,z:b.z+1,y:1.3,vx:(state.playerX-(b.x+i*.65))*.23,vz:12,life:3,damage:15,active:true,boss:true})}
function updateShots(dt){for(let i=state.bullets.length-1;i>=0;i--){const b=state.bullets[i];if(!b.active)continue;b.x+=b.vx*dt;b.z+=b.vz*dt;b.life-=dt;b.group.position.set(b.x,1.28,b.z);b.group.rotation.y=Math.atan2(b.vx,-b.vz);if(processBulletCollisions(b,dt)||b.life<=0||b.z<-60)releaseBullet(b)}const beam=state.laserBeam;if(beam){beam.life-=dt;beam.group.visible=beam.life>0}
for(let i=state.enemyShots.length-1;i>=0;i--){const s=state.enemyShots[i];if(!s.active){if(state.time<s.warningAt)continue;s.active=true;s.mesh=mesh(G.sphere,mat('enemyShot','#ff624d',.26,.2,1.4),scene,[s.x,s.y,s.z],[.16,.16,.16])}s.x+=s.vx*dt;s.z+=s.vz*dt;s.life-=dt;s.mesh.position.set(s.x,s.y,s.z);s.mesh.rotation.x+=dt*4;if(Math.abs(s.z-playerZ)<.65&&Math.abs(s.x-state.playerX)<.72){hurtPlayer(s.damage,.8);burst3D(s.x,.8,s.z,'#ff745b',9);scene.remove(s.mesh);state.enemyShots.splice(i,1);continue}if(s.life<=0||s.z>playerZ+1){scene.remove(s.mesh);state.enemyShots.splice(i,1)}}}
function hurtPlayer(amount,cooldown){if(state.invuln>0||state.mode!=='playing')return;state.hp=Math.max(0,state.hp-amount);state.invuln=cooldown;state.shake=Math.max(state.shake,.17);audio.impact(true);navigator.vibrate?.(26);burst3D(state.playerX,.8,playerZ,'#ff685e',12);$('#healthBar').style.width=state.hp+'%';$('#healthText').textContent=Math.ceil(state.hp);if(state.hp<=0)endGame()}
function updateGatesCrates(dt){for(let i=state.gates.length-1;i>=0;i--){const g=state.gates[i];g.z+=worldSpeed()*dt;g.group.position.z=g.z;g.phase+=dt;g.scan.position.y=1+((g.phase*1.8)%3.4);g.light.intensity=4+Math.sin(g.phase*4)*1.3;if(!g.resolved&&g.z>playerZ-1.1){g.resolved=true;if(Math.abs(state.playerX-g.x)<1.92){acquireGate(g);g.group.scale.setScalar(1.16);burst3D(g.x,2,g.z,g.reward.color,24)}else announce('强化路线错过','下次提前向奖励侧移动');g.group.visible=false}if(g.z>playerZ+5){disposeGroup(g.group);state.gates.splice(i,1)}}for(let i=state.crates.length-1;i>=0;i--){const c=state.crates[i];c.z+=worldSpeed()*dt;c.group.position.z=c.z;c.spin+=dt;c.group.rotation.y=Math.sin(c.spin)*.07;c.group.position.y=.42+Math.sin(c.spin*2)*.09;c.light.intensity=3.4+Math.sin(c.spin*5)*1.1;if(Math.abs(c.z-playerZ)<1.25&&Math.abs(c.x-state.playerX)<1.3){setWeapon(c.type);state.score+=100;burst3D(c.x,1,c.z,weaponInfo[c.type].color,26);disposeGroup(c.group);state.crates.splice(i,1);continue}if(c.z>playerZ+3){disposeGroup(c.group);state.crates.splice(i,1)}}}
function worldSpeed(){return 6.3+Math.min(2.7,state.time*.018)}
function updateEffects(dt){for(let i=state.effects.length-1;i>=0;i--){const p=state.effects[i];p.userData.life-=dt;if(p.userData.warning){p.material.opacity=Math.max(0,p.userData.life*1.1);if(p.userData.life<=0){scene.remove(p);p.geometry.dispose();p.material.dispose();state.effects.splice(i,1)}continue}p.userData.v.y-=9*dt;p.position.addScaledVector(p.userData.v,dt);p.material.opacity=Math.max(0,p.userData.life/p.userData.max);p.scale.multiplyScalar(.985);if(p.userData.life<=0){p.visible=false;scene.remove(p);particlePool.push(p);state.effects.splice(i,1)}}for(let i=state.floating.length-1;i>=0;i--){const f=state.floating[i];f.life-=dt;f.mesh.position.y+=dt*.85;f.mesh.material.opacity=Math.max(0,f.life/f.max);f.mesh.scale.multiplyScalar(1+dt*.2);if(f.life<=0){scene.remove(f.mesh);f.texture.dispose();f.mesh.material.dispose();state.floating.splice(i,1)}}}
function updateDecor(dt){worldTime+=dt;if(roadTexture)roadTexture.offset.y=(roadTexture.offset.y+worldSpeed()*dt/120)%1;let dirty=false;for(const b of worldObjects.buildings){b.z+=worldSpeed()*dt;if(b.z>18)b.z-=140;dirty=true}if(dirty)updateWorldInstances();for(const r of worldObjects.rocks){r.z+=worldSpeed()*dt;if(r.z>10)r.z=-105}updateRockInstances();for(const l of worldObjects.lamps){l.z+=worldSpeed()*dt;if(l.z>15)l.z-=66;l.group.position.z=l.z}}
function updateGame(dt){if(state.mode!=='playing')return;dt=Math.min(.04,dt);state.time+=dt;worldTime+=dt;state.invuln=Math.max(0,state.invuln-dt);state.shootTimer-=dt;state.playerX=mix(state.playerX,state.targetX,Math.min(1,dt*10));playerRig.position.x=state.playerX;playerRig.position.y=Math.sin(state.time*8)*.018;const moving=Math.abs(state.playerX-state.targetX)>.08;playerParts.legL.rotation.x=moving?Math.sin(state.time*13)*.62:Math.sin(state.time*2)*.025;playerParts.legR.rotation.x=moving?-Math.sin(state.time*13)*.62:Math.sin(state.time*2)*.025;playerParts.armL.rotation.x=moving?-.15+Math.sin(state.time*13)*.12:-.18;playerParts.armR.rotation.x=-.68+(state.weapon==='shotgun'&&state.shake>.1?.18:0);playerRig.rotation.z=mix(playerRig.rotation.z,clamp((state.targetX-state.playerX)*-.09,-.12,.12),dt*4);if(state.invuln>0)playerRig.visible=Math.floor(state.invuln*16)%2===0;else playerRig.visible=true;playerShadow.position.x=state.playerX;camera.position.x=mix(camera.position.x,state.playerX*.17,dt*1.8);camera.lookAt(state.playerX*.08,1.2,-9);state.shootTimer<=0&&fireWeapon();updateDifficulty(dt);moveThreats(dt);updateBoss(dt);updateShots(dt);updateGatesCrates(dt);updateEffects(dt);updateDecor(dt);state.score=Math.max(0,state.score+dt*1.15);state.hp=Math.max(0,state.hp);if(state.threats.length>24){for(const e of state.threats.splice(0,state.threats.length-24)){disposeSoldier(e.group);scene.remove(e.shadow)}}if(state.time-state.lastHud>.1){state.lastHud=state.time;updateHud()}if(state.hp<=0&&state.mode==='playing')endGame()}
function updateHud(){const mins=String(Math.floor(state.time/60)).padStart(2,'0'),secs=String(Math.floor(state.time%60)).padStart(2,'0');$('#clock').textContent=`${mins}:${secs}`;$('#score').textContent=String(Math.floor(state.score)).padStart(4,'0');$('#healthBar').style.width=state.hp+'%';$('#healthText').textContent=Math.ceil(state.hp);let label=state.time<15?'边境荒原 · 初始接触':state.time<40?'废城外环 · 敌潮增援':state.time<70?'破碎公路 · 重装来袭':state.boss?'巨像交战 · 高危警报':'深区突围 · 怪潮狂袭';$('#stage').textContent=label;if(state.time>5)$('#touchHint').classList.add('hidden');$('#best').textContent=state.best}
function updateWeaponUi(){$('#weaponName').textContent=weaponInfo[state.weapon].name;$('#weaponMeta').textContent=weaponInfo[state.weapon].sub+` · 弹道 ${state.stats.lanes} / 弹丸 ${state.stats.pellets}`;$('#weaponIcon').textContent=weaponInfo[state.weapon].icon;$('#weaponIcon').style.color=weaponInfo[state.weapon].color;$('#weaponRank').textContent=['Mk.I','Mk.II','Mk.III','Mk.IV','Mk.V'][state.weaponLevel-1]||'Mk.IX'}
let toastTimer=0,comboTimer=0;function announce(title,sub=''){const el=$('#upgradeToast');el.innerHTML=`${title}${sub?`<small>${sub}</small>`:''}`;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1600)}
function showCombo(text){const el=$('#comboToast');el.textContent=text;el.classList.add('show');clearTimeout(comboTimer);comboTimer=setTimeout(()=>el.classList.remove('show'),950)}
function endGame(){if(state.mode!=='playing')return;state.mode='ended';audio.pause();state.best=Math.max(state.best,Math.floor(state.score));saved.set('mr2-best',state.best);$('#endTime').textContent=`${String(Math.floor(state.time/60)).padStart(2,'0')}:${String(Math.floor(state.time%60)).padStart(2,'0')}`;$('#endKills').textContent=state.kills;$('#endScore').textContent=Math.floor(state.score);$('#endBest').textContent=state.best;$('#endTitle').textContent=state.time<15?'战斗结束':'突围报告';$('#hud').classList.add('hidden');$('#endPanel').classList.remove('hidden')}
function clearDynamic(){for(const e of state.threats){disposeSoldier(e.group);scene.remove(e.shadow)}for(const g of state.gates)disposeGroup(g.group);for(const c of state.crates)disposeGroup(c.group);for(const s of state.enemyShots)if(s.mesh)scene.remove(s.mesh);for(const p of state.effects)scene.remove(p);for(const f of state.floating){scene.remove(f.mesh);f.texture.dispose();f.mesh.material.dispose()}state.threats.length=state.gates.length=state.crates.length=state.enemyShots.length=state.effects.length=state.floating.length=0;for(const b of state.bullets)releaseBullet(b);if(state.boss){disposeSoldier(state.boss.group);state.boss=null}if(state.laserBeam){scene.remove(state.laserBeam.group);state.laserBeam=null}$('#bossHud').classList.add('hidden');audio.setBoss(false)}
function resetRun(){clearDynamic();state.time=0;state.score=0;state.kills=0;state.hp=100;state.playerX=state.targetX=0;state.invuln=0;state.shootTimer=.2;state.spawnTimer=1.3;state.gateTimer=3.7;state.crateTimer=11;state.nextBoss=78;state.damageBonus=0;state.combo=0;state.lastHit=0;state.shake=0;state.stats={lanes:1,pellets:1,fireRate:1,bulletSpeed:1,damage:1};playerRig.position.set(0,0,playerZ);playerRig.visible=true;setWeapon('rifle',true);updateWeaponUi();updateHud()}
async function startRun(){resetRun();state.mode='playing';$('#menu').classList.add('hidden');$('#pausePanel').classList.add('hidden');$('#endPanel').classList.add('hidden');$('#settingsPanel').classList.add('hidden');$('#hud').classList.remove('hidden');$('#touchHint').classList.remove('hidden');await audio.start();lastFrame=performance.now()}
async function pauseRun(){if(state.mode==='playing'){state.mode='paused';$('#pausePanel').classList.remove('hidden');await audio.pause()}else if(state.mode==='paused'){state.mode='playing';$('#pausePanel').classList.add('hidden');await audio.resume();lastFrame=performance.now()}}
function setModeMenu(){clearDynamic();state.mode='menu';state.time=0;playerRig.position.x=0;playerRig.visible=true;$('#hud').classList.add('hidden');$('#pausePanel').classList.add('hidden');$('#endPanel').classList.add('hidden');$('#settingsPanel').classList.add('hidden');$('#menu').classList.remove('hidden');audio.pause()}
function setupUi(){const persist=(id,key,otherIds)=>{const slider=$(id),v=+saved.get(key,key==='mr2-music'?'.55':'.75')*100;slider.value=v;const set=value=>{const n=+value/100;saved.set(key,n);if(key==='mr2-music')audio.setMusic(n);else audio.setSfx(n);const display=Math.round(value)+'%';const output={'#menuMusicVolume':'#menuMusicValue','#menuSfxVolume':'#menuSfxValue'};for(const k of otherIds){$(k).value=value;$(output[k]).textContent=display}};slider.addEventListener('input',e=>set(e.target.value));for(const k of otherIds)$(k).addEventListener('input',e=>set(e.target.value));for(const k of otherIds){$(k).value=v;const output={'#menuMusicVolume':'#menuMusicValue','#menuSfxVolume':'#menuSfxValue'};$(output[k]).textContent=Math.round(v)+'%'}set(v)};persist('#musicVolume','mr2-music',['#menuMusicVolume']);persist('#sfxVolume','mr2-sfx',['#menuSfxVolume']);$('#start').addEventListener('click',startRun);$('#again').addEventListener('click',startRun);$('#restart').addEventListener('click',startRun);$('#pause').addEventListener('click',pauseRun);$('#resume').addEventListener('click',pauseRun);$('#home').addEventListener('click',setModeMenu);$('#endHome').addEventListener('click',setModeMenu);$('#openSettings').addEventListener('click',()=>$('#settingsPanel').classList.remove('hidden'));$('#closeSettings').addEventListener('click',()=>$('#settingsPanel').classList.add('hidden'));$('#best').textContent=state.best;canvas.addEventListener('pointerdown',e=>{if(state.mode!=='playing')return;e.preventDefault();try{canvas.setPointerCapture?.(e.pointerId)}catch{}activeTouches++;movePointer(e)});canvas.addEventListener('pointermove',e=>{if(state.mode==='playing'&&(e.buttons||e.pointerType==='touch')){e.preventDefault();movePointer(e)}});canvas.addEventListener('pointerup',()=>activeTouches=Math.max(0,activeTouches-1));canvas.addEventListener('pointercancel',()=>activeTouches=0);document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.mode==='playing')pauseRun()});addEventListener('keydown',e=>{if(e.key==='Escape'&&state.mode==='playing')pauseRun()})}
function movePointer(e){const r=canvas.getBoundingClientRect(),n=(e.clientX-r.left)/r.width;state.targetX=clamp((n-.5)*2*PLAYER_LIMIT,-PLAYER_LIMIT,PLAYER_LIMIT)}
function resize(){if(!renderer)return;W=innerWidth;H=innerHeight;renderer.setSize(W,H,false);renderer.setPixelRatio(Math.min(devicePixelRatio||1,lowFps>0?1:1.35));camera.aspect=W/H;camera.updateProjectionMatrix()}
function frame(now){requestAnimationFrame(frame);const elapsedFrame=now-lastFrame,dt=Math.min(.04,Math.max(0,elapsedFrame||16)/1000);lastFrame=now;if(state.mode==='playing')updateGame(dt);else if(playerRig){playerRig.position.y=Math.sin(now*.0011)*.012;updateDecor(dt*.18)}const shake=state.shake,baseX=camera.position.x,baseY=camera.position.y;cameraBaseQ.copy(camera.quaternion);if(shake>0&&state.mode==='playing'){camera.position.x+=rand(-shake,shake);camera.position.y+=rand(-shake*.45,shake*.45);state.shake=Math.max(0,shake-dt*.65)}renderer.render(scene,camera);camera.position.x=baseX;camera.position.y=baseY;camera.quaternion.copy(cameraBaseQ);if(now-fpsT>2500){const fps=frameCount*1000/(now-fpsT);if(fps<39){lowFps++;if(lowFps>=2)renderer.setPixelRatio(Math.min(devicePixelRatio||1,1));}else lowFps=Math.max(0,lowFps-1);fpsT=now;frameCount=0}frameCount++}
addEventListener('resize',resize,{passive:true});document.addEventListener('contextmenu',e=>e.preventDefault());
init();
if('serviceWorker'in navigator&&location.protocol.startsWith('http'))addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
if(new URLSearchParams(location.search).has('test'))window.__MR_TEST__={start:startRun,reset:resetRun,update:updateGame,step(seconds){let n=Math.ceil(seconds/.025);for(let i=0;i<n&&state.mode==='playing';i++)updateGame(seconds/n);return this.state()},spawnEnemy,spawnGateEvent,previewGates(z=-12){spawnGateEvent();for(const g of state.gates){g.z=z;g.group.position.z=z}},previewCrate(type='plasma',z=-16){spawnCrate(type,0,z)},spawnCrate,setWeapon,spawnBoss:buildBoss,setTime(t){state.time=t;state.nextBoss=t+999},setSpawnTimer(t){state.spawnTimer=t},fire:fireWeapon,damageEnemy,damageBoss,hurtPlayer,collectReward(reward,x=0){state.playerX=state.targetX=x;playerRig.position.x=x;const r={type:'damage',amount:.2,value:'伤害 +20%',name:'测试增益',color:'#73ffff',...reward};buildGate(r,x,playerZ-1.3);updateGatesCrates(.04);return this.state()},testGateCharge(){const r={type:'rate',amount:.15,value:'射速 +15%',name:'高速供弹',color:'#73ffff'};buildGate(r,state.playerX,playerZ-.5);const g=state.gates.at(-1);const b=acquireBullet();b.x=g.x;b.z=g.z;b.vx=0;b.vz=0;b.group.position.set(b.x,1.2,b.z);processBulletCollisions(b,.01);return g.charge},forceCrate(type){spawnCrate(type,state.playerX,playerZ-1.2);updateGatesCrates(.04);return this.state()},forcePlayerX(x){state.playerX=state.targetX=clamp(x,-PLAYER_LIMIT,PLAYER_LIMIT);playerRig.position.x=state.playerX},clearBullets(){for(const b of state.bullets)releaseBullet(b)},metrics(){const active=state.bullets.filter(x=>x.active);return{count:active.length,avgSpeed:active.length?active.reduce((a,b)=>a+Math.hypot(b.vx,b.vz),0)/active.length:0,totalDamage:active.reduce((a,b)=>a+b.damage,0),weapon:state.weapon,interval:weaponInfo[state.weapon].interval/state.stats.fireRate,lanes:state.stats.lanes,pellets:state.stats.pellets,damageMultiplier:state.stats.damage,bulletSpeedMultiplier:state.stats.bulletSpeed,kinds:[...new Set(active.map(x=>x.kind))],gunMeshes:(()=>{let n=0;weaponRoot?.traverse(o=>{if(o.isMesh)n++});return n})(),playerMeshes:(()=>{let n=0;playerRig?.traverse(o=>{if(o.isMesh)n++});return n})(),drawCalls:renderer.info.render.calls,laser:!!state.laserBeam?.group.visible}},difficulty:[0,15,40,70,78,90,150,250].map(t=>({time:t,interval:spawnInterval(t)})),state:()=>({mode:state.mode,time:state.time,hp:state.hp,score:state.score,kills:state.kills,weapon:state.weapon,playerX:state.playerX,targetX:state.targetX,stats:{...state.stats},enemies:state.threats.length,gates:state.gates.length,crates:state.crates.length,boss:!!state.boss,bossHp:state.boss?.hp,enemyShots:state.enemyShots.length,bullets:state.bullets.filter(x=>x.active).length,audio:audio.status()}),playerProjection(){playerRig.updateMatrixWorld(true);const f=new THREE.Vector3(0,1.8,0).applyMatrix4(playerRig.matrixWorld).project(camera),feet=new THREE.Vector3(0,0,0).applyMatrix4(playerRig.matrixWorld).project(camera);return{headY:(1-f.y)*H/2,feetY:(1-feet.y)*H/2,headNdc:f.y,feetNdc:feet.y}},getEnemy(){return state.threats[0]},getGate(){return state.gates[0]},getAudio:()=>audio.status(),};
